#!/usr/bin/env bash
# FoleyTimePro — multi-company deploy script
#
# Usage:
#   ./deploy.sh --company acme --port 8081
#   ./deploy.sh --company beta --port 8082
#   ./deploy.sh --company acme --port 8081 --down
#
# Each company gets isolated containers, DB, volume, and network.
# Passwords are auto-generated on first deploy and saved to companies/<name>.env

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
COMPOSE_FILE="$SCRIPT_DIR/docker-compose.yml"
COMPANIES_DIR="$SCRIPT_DIR/companies"

COMPANY=""
PORT=""
ACTION="up"

usage() {
    echo "Usage: $0 --company <name> --port <port> [--down]"
    echo ""
    echo "  --company  Company identifier (used for container/DB names)"
    echo "  --port     Host port for the web server"
    echo "  --down     Stop and remove containers (keeps data volumes)"
    echo ""
    echo "Examples:"
    echo "  $0 --company acme --port 8081"
    echo "  $0 --company beta --port 8082"
    echo "  $0 --company acme --port 8081 --down"
    exit 1
}

# Parse args
while [[ $# -gt 0 ]]; do
    case "$1" in
        --company|-c) COMPANY="$2"; shift 2 ;;
        --port|-p)    PORT="$2";    shift 2 ;;
        --down)       ACTION="down"; shift ;;
        --help|-h)    usage ;;
        *) echo "Unknown option: $1"; usage ;;
    esac
done

if [[ -z "$COMPANY" || -z "$PORT" ]]; then
    usage
fi

# Sanitize: lowercase, alphanumeric + hyphens only
COMPANY="${COMPANY,,}"
COMPANY="${COMPANY//[^a-z0-9-]/-}"

ENV_FILE="$COMPANIES_DIR/$COMPANY.env"
mkdir -p "$COMPANIES_DIR"

# ── Down ────────────────────────────────────────────────────────────────────
if [[ "$ACTION" == "down" ]]; then
    if [[ ! -f "$ENV_FILE" ]]; then
        echo "No config found for '$COMPANY' at $ENV_FILE"
        exit 1
    fi
    echo "Stopping $COMPANY..."
    docker compose -p "$COMPANY" --env-file "$ENV_FILE" -f "$COMPOSE_FILE" down
    echo "Done. Data volumes are preserved."
    exit 0
fi

# ── Validate port is numeric ─────────────────────────────────────────────────
if ! [[ "$PORT" =~ ^[0-9]+$ ]]; then
    echo "Error: --port must be a number (got: $PORT)"
    exit 1
fi

# ── Create env file on first deploy ─────────────────────────────────────────
if [[ ! -f "$ENV_FILE" ]]; then
    echo "New deployment — generating config for: $COMPANY"

    DB_PASS="$(openssl rand -base64 32 | tr -dc 'a-zA-Z0-9' | head -c 32)"
    DB_ROOT_PASSWORD="$(openssl rand -base64 32 | tr -dc 'a-zA-Z0-9' | head -c 32)"

    cat > "$ENV_FILE" <<EOF
# FoleyTimePro — $COMPANY deployment
# Auto-generated by deploy.sh on $(date -u '+%Y-%m-%d %H:%M UTC')
# Keep this file secret — it contains database credentials.

COMPANY=$COMPANY
APP_PORT=$PORT

DB_NAME=timeclock_$COMPANY
DB_USER=timeclock
DB_PASS=$DB_PASS
DB_ROOT_PASSWORD=$DB_ROOT_PASSWORD

# Adjust timezone if needed (default: America/Chicago)
DB_TIMEZONE=America/Chicago
EOF
    echo "  Config saved: $ENV_FILE"
else
    echo "Using existing config: $ENV_FILE"
    # Update port in case it was changed via flag
    sed -i "s/^APP_PORT=.*/APP_PORT=$PORT/" "$ENV_FILE"
fi

# ── Deploy ───────────────────────────────────────────────────────────────────
echo ""
echo "Starting $COMPANY on port $PORT..."
docker compose -p "$COMPANY" --env-file "$ENV_FILE" -f "$COMPOSE_FILE" up -d --pull always

echo ""
echo "Status:"
docker compose -p "$COMPANY" --env-file "$ENV_FILE" -f "$COMPOSE_FILE" ps

HOST_IP="$(hostname -I | awk '{print $1}')"
echo ""
echo "Access FoleyTimePro ($COMPANY) at:  http://$HOST_IP:$PORT"
